      { question: "What does a foreign key enforce?", options: ["Uniqueness", "Referential integrity (can't reference a non-existent row)", "Not-null", "Data type"], answer: 1, explanations: ["That's a primary key/unique constraint.", "Correct — a foreign key enforces referential integrity: you can't insert a row that references a non-existent parent row.", "That's NOT NULL.", "That's the column type."], difficulty: "medium" },
      { question: "Why prefer a surrogate key (auto-increment id) over a natural key (email)?", options: ["It's faster", "It's immutable — natural keys can change, breaking all references", "It's smaller", "It's required"], answer: 1, explanations: ["Speed isn't the main reason.", "Correct — natural keys (email, SSN) can change, breaking all foreign key references. Surrogate keys are immutable.", "Size isn't the main reason.", "Not required but strongly recommended."], difficulty: "medium" }
